from primitive_api import (
    step_text_action,
    inspect_current_state,
    filter_actions,
    check_success,
    look,
)

def go_to_room(target):
    visited = set()
    for _ in range(15):
        state = inspect_current_state()
        loc = state.get("current_location")
        visited.add(loc)
        if loc == target or "inclined plane" in look():
            return loc
        go_acts = filter_actions(startswith="go to ")
        open_acts = filter_actions(startswith="open door to ")
        # If there's a closed door to an unvisited place, open it
        # First check if target door is visible
        if f"go to {target}" in go_acts:
            step_text_action(f"go to {target}")
            continue
        if f"open door to {target}" in open_acts:
            step_text_action(f"open door to {target}")
            step_text_action(f"go to {target}")
            continue
        # Prefer hallway, kitchen, foyer, corridor
        moved = False
        for pref in ["workshop", "hallway", "corridor", "foyer", "kitchen", "living room"]:
            if pref not in visited:
                if f"open door to {pref}" in open_acts:
                    step_text_action(f"open door to {pref}")
                if f"go to {pref}" in filter_actions(startswith="go to "):
                    step_text_action(f"go to {pref}")
                    moved = True
                    break
        if not moved:
            for act in go_acts:
                dest = act.replace("go to ", "").replace("door to ", "")
                if dest not in visited and not act.startswith("go to door"):
                    step_text_action(act)
                    moved = True
                    break
        if not moved:
            break
    return inspect_current_state().get("current_location")

loc = go_to_room("workshop")
state = inspect_current_state(query=["inclined plane", "block", "move", "focus", "wait"])
print("LOC:", loc)
print("LOOK:\n", look())
print("QUERY ACTIONS:", state.get("query_actions"))
print("SUCCESS:", check_success())

